const schema = $json;
const themeProperty = schema.properties.variation_theme.items.properties.name;

const validThemes = themeProperty.enum || [];
const deprecatedThemes = (themeProperty.$lifecycle && themeProperty.$lifecycle.enumDeprecated) || [];

const definition = $('Get Product Type Definition').item.json;

// Checked before any schema parsing is attempted. Not a general
// solution - a small, explicit set of answers actually confirmed
// against real Amazon submissions today, keyed by product type.
// Deliberately kept minimal by design decision, not by omission - the
// general pipeline below (schema candidates + real listing data, done
// downstream of this workflow) is meant to be the main mechanism, not
// this list. Do not add entries here reactively just because a new
// theme resolves ambiguously; that defeats the point of building the
// general mechanism in the first place.
const KNOWN_VERIFIED_ATTRIBUTES = {
  SHIRT: { COLOR: 'color' }
};

function findRealAttribute(dimensionName) {
  const allOfEntries = Array.isArray(schema.allOf) ? schema.allOf : [];
  const dimLower = dimensionName.toLowerCase();
  const matchedEntries = [];
  // Collects every plausible match across every matching block, rather
  // than stopping at the first one found. A product type's schema can
  // genuinely have more than one attribute that looks plausible for the
  // same theme name - confirmed live on SHIRT/SIZE, which matches both
  // shirt_size and special_size_type. Returning early on the first hit
  // meant this heuristic could never even know a second candidate
  // existed, let alone that it might be the correct one. Disambiguating
  // between multiple candidates is a separate, later step using real
  // listing data, not schema alone - this function's job is only to
  // report everything schema-plausible, never to pick a winner itself.
  const candidates = [];

  for (const entry of allOfEntries) {
    const ifBlock = entry.if;
    const thenBlock = entry.then;
    if (!ifBlock || !thenBlock) continue;

    const ifStr = JSON.stringify(ifBlock).toLowerCase();
    if (ifStr.indexOf(dimLower) === -1) continue;

    const required = Array.isArray(thenBlock.required)
      ? thenBlock.required
      : (thenBlock.properties ? Object.keys(thenBlock.properties) : []);

    matchedEntries.push({ if_snippet: JSON.stringify(ifBlock).slice(0, 300), required: required });

    const plausible = required.find(function(name) {
      return name.toLowerCase().indexOf(dimLower) !== -1;
    });
    if (plausible && candidates.indexOf(plausible) === -1) {
      candidates.push(plausible);
    }
  }
  return { attributes: candidates, matched_entries: matchedEntries };
}

// Resolved once per theme here, for every valid theme, rather than
// separately later for whichever one gets picked - themes are few
// enough per product type that this is cheap, and it means the
// frontend never needs a second round trip once a theme is chosen.
//
// theme_attribute_map[theme] is now an array of arrays - one array of
// candidate attribute names per dimension, not one name per dimension.
// A single-candidate dimension is still an array (length 1), for a
// consistent shape regardless of how many candidates were found or
// which path (known-verified vs schema-parsed) produced them.
const themeAttributeMap = {};
const themeAttributeDebug = {};
const knownForThisProductType = KNOWN_VERIFIED_ATTRIBUTES[definition.productType] || {};
for (const theme of validThemes) {
  const dims = theme.split('/');
  const resolved = dims.map(function(d) {
    if (knownForThisProductType[d]) {
      return { attributes: [knownForThisProductType[d]], matched_entries: [{ source: 'known_verified', reason: 'confirmed against a real Amazon submission today, not schema-parsed' }] };
    }
    return findRealAttribute(d);
  });
  themeAttributeMap[theme] = resolved.map(function(r) { return r.attributes; });
  themeAttributeDebug[theme] = resolved.map(function(r) { return r.matched_entries; });
}

const inspectName = $('Validate Input').first().json.inspect_attribute;
const inspectedSchema = inspectName && schema.properties ? (schema.properties[inspectName] || null) : null;

return {
  json: {
    product_type: definition.productType,
    marketplace_id: definition.marketplaceIds[0],
    valid_themes: validThemes,
    deprecated_themes: deprecatedThemes,
    theme_attribute_map: themeAttributeMap,
    theme_attribute_debug: themeAttributeDebug,
    product_type_version: definition.productTypeVersion.version,
    schema_required: Array.isArray(schema.required) ? schema.required : [],
    // Added for the structured-attribute design: the requested
    // attribute's own schema definition, generically - whatever
    // properties/required/enum it declares, not hardcoded to shirt_size
    // specifically. null if inspect_attribute wasn't set, or if this
    // product type's schema has no property by that name.
    inspected_attribute: inspectName,
    inspected_attribute_schema: inspectedSchema
  }
};

const rawInput = $input.first().json;
const body = rawInput.body ? rawInput.body : rawInput;

if (!body.seller_id) {
  return [{ json: { decision: 'REJECTED', reason: 'MISSING_SELLER_ID', message: 'seller_id is required.' } }];
}
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(body.seller_id)) {
  return [{ json: { decision: 'REJECTED', reason: 'INVALID_SELLER_ID_FORMAT', message: 'seller_id must be a valid UUID.' } }];
}
if (!body.product_type || !body.marketplace_id) {
  return [{ json: { decision: 'REJECTED', reason: 'MISSING_REQUIRED_FIELDS', message: 'product_type and marketplace_id are both required.' } }];
}

return [{ json: {
  decision: 'VALID',
  seller_id: body.seller_id,
  product_type: body.product_type,
  marketplace_id: body.marketplace_id,
  // Optional. When set, the response also includes this attribute's own
  // schema definition (properties/required/enum) - generic by design,
  // not specific to shirt_size, so this same diagnostic can answer the
  // same question for whatever structured attribute turns up next.
  inspect_attribute: body.inspect_attribute || null
}}];

const status = $input.first().json;
  return [{ json: {
    decision: 'REJECTED',
    reason: 'RATE_LIMITED',
    current_count: status.current_count,
    window_start: status.window_start,
    message: 'This seller has made too many requests to this operation in the current window. Please retry shortly.'
  }}];

const sellerRows = $input.first().json;
const sellerRow = Array.isArray(sellerRows) ? sellerRows[0] : sellerRows;
const ctx = $('Validate Input').first().json;

if (!sellerRow) {
  return [{ json: {
    decision: 'REJECTED',
    reason: 'SELLER_NOT_FOUND',
    seller_id: ctx.seller_id,
    message: 'No seller record exists for this seller_id.'
  }}];
}

if (sellerRow.status !== 'active') {
  return [{ json: {
    decision: 'REJECTED',
    reason: 'SELLER_NOT_ACTIVE',
    seller_id: ctx.seller_id,
    seller_status: sellerRow.status,
    message: 'This seller account is not active (status: ' + sellerRow.status + '). Access is not permitted.'
  }}];
}

return [{ json: { decision: 'ELIGIBLE' } }];
